From 8b4a2891d9e4ca8ac835527cc7d114ab08e89ea7 Mon Sep 17 00:00:00 2001
From: Albert Astals Cid <aacid@kde.org>
Date: Fri, 8 Nov 2019 00:43:05 +0100
Subject: [PATCH] Fix uninitialized memory use in
 JBIG2Stream::readTextRegionSeg

When the unlikely condition triggers
---
 poppler/JBIG2Stream.cc | 5 ++++-
 1 file changed, 4 insertions(+), 1 deletion(-)

diff --git a/poppler/JBIG2Stream.cc b/poppler/JBIG2Stream.cc
index 09e5b6c..48554d8 100644
--- a/poppler/JBIG2Stream.cc
+++ b/poppler/JBIG2Stream.cc
@@ -2263,7 +2263,10 @@ void JBIG2Stream::readTextRegionSeg(unsigned int segNum, bool imm,
 	  symCodeTab[i++].prefixLen = 0;
 	}
       } else if (j > 0x100) {
-	if (unlikely(i == 0)) ++i;
+	if (unlikely(i == 0)) {
+	  symCodeTab[i].prefixLen = 0;
+	  ++i;
+	}
 	for (j -= 0x100; j && i < numSyms; --j) {
 	  symCodeTab[i].prefixLen = symCodeTab[i-1].prefixLen;
 	  ++i;
-- 
2.55.0
